# Also, let's verify our coin triple generation is correct
print("Verifying coin triple constraints:")
for triple in coin_triples:
    x, y, z = triple
    if max(x, y, z) < 2:
        print(f"ERROR: {triple} has no box with >= 2 coins")
    if not (abs(x - y) == 6 or abs(x - z) == 6 or abs(y - z) == 6):
        print(f"ERROR: {triple} has no pair differing by 6")
    if x + y + z != 30:
        print(f"ERROR: {triple} doesn't sum to 30")

print(f"\nTotal coin triples: {len(coin_triples)}")

# Let's also check if we missed any distributions
# Alternative generation method
alt_triples = []
for x in range(31):
    for y in range(31 - x):
        z = 30 - x - y
        if max(x, y, z) >= 2:
            diffs = [abs(x-y), abs(x-z), abs(y-z)]
            if 6 in diffs:
                alt_triples.append((x, y, z))

print(f"Alternative generation gives: {len(alt_triples)} triples")
print("Sets equal?", set(coin_triples) == set(alt_triples))", "session_id": 1774283146}

