from collections import defaultdict

# ========== Subtask 1 Script Recreation ==========
def payoff(guess, coin):
    """Return payoff for a given guess triple and coin triple."""
    best = float('inf')
    for perm in itertools.permutations(range(3)):
        total = 0
        for i in range(3):
            if guess[i] <= coin[perm[i]]:
                total += guess[i]
        best = min(best, total)
    return best

def compute_optimal():
    """Compute max guaranteed coins from subtask 1."""
    # Generate all feasible coin triples
    feasible_coins = []
    for x in range(31):
        for y in range(31 - x):
            z = 30 - x - y
            # Conditions: sum = 30, all non-negative, at least one ≥ 2, ∃ pair with difference 6
            if x >= 0 and y >= 0 and z >= 0:
                if max(x, y, z) >= 2:  # at least one ≥ 2
                    # Check if there exist i,j with |x_i - x_j| = 6
                    diffs = [abs(x-y), abs(x-z), abs(y-z)]
                    if 6 in diffs:
                        feasible_coins.append((x, y, z))

    # Generate all guess triples
    max_guarantee = 0
    optimal_guesses = []

    for g1 in range(31):
        for g2 in range(31):
            for g3 in range(31):
                guess = (g1, g2, g3)
                # Compute guaranteed payoff
                min_pay = float('inf')
                for coin in feasible_coins:
                    min_pay = min(min_pay, payoff(guess, coin))
                    if min_pay == 0:  # early stopping
                        break

                if min_pay > max_guarantee:
                    max_guarantee = min_pay
                    optimal_guesses = [guess]
                elif min_pay == max_guarantee:
                    optimal_guesses.append(guess)

    return max_guarantee, optimal_guesses

# ========== Run the script 10 times ==========
print("=== Verification Step 1: Run script 10 times ===")
